            'intro' => 'প্রথম দিনে যা জানা আছে তা দিয়েই একটি অ্যাসেট রেকর্ড করা যায় - নাম, ধরন ও সিরিয়াল - বাকিটা পরে পূরণ করা যায়। <strong>প্রত্যাশিত তথ্য</strong> বলে দেয় প্রতিটি অ্যাসেটের ধরনে শেষ পর্যন্ত কোন ফিল্ডগুলো থাকা উচিত, আর <strong>অনুপস্থিত তথ্য</strong> এমন প্রতিটি অ্যাসেট তালিকাভুক্ত করে যেখানে এখনও কোনোটি নেই, ফিল্ডের নামসহ। কিছুই কখনও প্রত্যাখ্যান করা হয় না: পেজ, ইমপোর্ট, REST API এবং ইনভেন্টরি এজেন্ট আগের মতোই সংরক্ষণ করে।',
            'p1' => '<strong>ফিল্ড বেছে নিন:</strong> সেটিংস -> অ্যাসেটের ধরন -> একটি ধরন -> <strong>প্রত্যাশিত তথ্য</strong>। বিল্ট-ইন ফিল্ড (পরিচয়, মেক ও মডেল, আর্থিক) এবং ওই ধরনের সাথে যুক্ত ফিল্ড সেটের যেকোনো কাস্টম ফিল্ডে টিক দিন। ধরনের লেআউটে কোনো সেকশন লুকালে তার ফিল্ডগুলো প্রযোজ্য নয় হয়ে যায় না।',
            'p2' => '<strong>তালিকা ধরে কাজ করুন:</strong> কোনো ধরন কিছু প্রত্যাশা করলেই হেডারে <strong>অনুপস্থিত তথ্য</strong> বোতাম দেখা যায়। ধরন, সেকশন (যেমন আর্থিক) বা ফিল্ড অনুযায়ী ফিল্টার করুন; খুলতে একটি অ্যাসেটে ক্লিক করুন। ফিল্ডটি - যেখানেই হোক - পূরণ করলে সেটি সাথে সাথে তালিকা থেকে চলে যায়; মুছে দিলে ফিরে আসে।',
            'p3' => '<strong>অনুপস্থিত</strong> মানে ফাঁকা: কোনো মান নেই, ফাঁকা টেক্সট বা কোনো নির্বাচন নেই। ০ খরচ বা "না" পূরণ করা হিসেবেই গণ্য - পরীক্ষা হলো মান আছে কি না, সঠিক কি না নয়। অবসরপ্রাপ্ত অ্যাসেট তালিকাভুক্ত হয় না।',
            'p4' => '<strong>প্রযোজ্য নয়</strong> একটি অ্যাসেটের একটি ফিল্ডকে আলাদা করে রাখে - যেমন ক্রয়মূল্যহীন একটি দান করা ল্যাপটপ। এটি ফিল্ডে কিছু লেখে না, অ্যাসেটের ইতিহাসে রেকর্ড হয় এবং অ্যাসেটে <strong>আনডু</strong> সহ দেখায়। এর জন্য অ্যাসেটে লেখার অ্যাক্সেস লাগে।',
        ],
        'retired' => [
            'nav' => 'অবসরপ্রাপ্ত অ্যাসেট',
            'heading' => 'অবসরপ্রাপ্ত অ্যাসেট',
            'intro' => 'যে সরঞ্জাম এস্টেট ছেড়ে চলে গেছে - বিক্রি বা নিষ্পত্তি হয়েছে, বাতিল হয়েছে, বা অন্য প্রতিষ্ঠানে স্থানান্তরিত হয়েছে - রেকর্ড হিসেবে রাখা হয়, কিন্তু আর সক্রিয় অ্যাসেট হিসেবে গণনা করা হয় না।',
            'p1' => '<strong>"অবসরপ্রাপ্ত" কাকে বলা হবে তা ঠিক করুন।</strong> <strong>সেটিংস &rarr; অ্যাসেট স্ট্যাটাস</strong>-এ একটি স্ট্যাটাস ("Retired", "Disposed", "Transferred") সম্পাদনা করে <strong>অবসরপ্রাপ্ত</strong>-এ টিক দিন। আপনি না দেওয়া পর্যন্ত কিছুই অবসরে যায় না।',
            'p2' => '<strong>একটি অ্যাসেট অবসরে পাঠাতে</strong> তাকে ওই স্ট্যাটাস দিন। তাতে তারিখের ছাপ পড়ে, আপনি কারণ যোগ করতে পারেন ("শিক্ষা মন্ত্রণালয়ে স্থানান্তরিত"), এবং সেটি অ্যাসেট তালিকা, টেবিল, ড্যাশবোর্ড, Watchtower, ওয়ারেন্টি ও লিজ অ্যালার্ট এবং ক্যালেন্ডার থেকে সরে যায়। আবার সাধারণ স্ট্যাটাস দিলে ফিরে আসে।',
            'p3' => 'তালিকার উপরের (এবং টেবিলের) <strong>অবসরপ্রাপ্ত দেখান</strong> অবসরপ্রাপ্ত অ্যাসেটগুলো আবার দৃশ্যমান করে। টেবিলে <strong>অবসরের তারিখ</strong> ও <strong>কারণ</strong> কলাম দেখানো এবং CSV বা PDF-এ এক্সপোর্ট করা যায় - স্থানান্তরের সাথে পাঠানোর তালিকা। রিপোর্ট প্যাকের <strong>অবসরপ্রাপ্ত অ্যাসেট</strong> ব্লক একটি সময়ে অবসরে যাওয়াগুলো তালিকাভুক্ত করে।',
            'p4' => 'যে অবসরপ্রাপ্ত মেশিন এখনও রিপোর্ট করে (ইনভেন্টরি এজেন্ট, Intune) তাকে চেনা যায় - কোনো ডুপ্লিকেট তৈরি হয় না - কিন্তু তার রেকর্ড বদলায় না: শুধু তার <em>সর্বশেষ দেখা</em> এগোয়, তাই নেটওয়ার্কে থাকা অবসরপ্রাপ্ত মেশিন ধরা পড়ে।',
        ],
        'review_heading' => 'যখন দুটি রেকর্ড একই জিনিস হতে পারে',
        'review_body' => 'FreeITSM কখনও আন্দাজ করে না। দুটি অ্যাসেটের সিরিয়াল নম্বর একই হলে, এজেন্ট পুরোনো মেশিনের নাম বহনকারী নতুন মেশিন পেলে, বা কোনো টুল এমন ডিভাইস রিপোর্ট করলে যার সিরিয়াল কোনো অ্যাসেটের সাথে (বা একাধিকের সাথে) মেলে না, তখন কেসটি <strong>সেটিংস &rarr; রিভিউ</strong>-এ অপেক্ষা করে, কোনো ব্যক্তির সিদ্ধান্তের জন্য। তালিকার একটি অ্যাসেট তার মূল তথ্যে সেটি জানায়। দুটি অ্যাসেটের জন্য: সেগুলোকে <strong>মার্জ</strong> করুন, <strong>ভিন্ন</strong> চিহ্নিত করুন (সত্যিই দুটি), বা <strong>উপেক্ষা</strong> করুন। অজানা ডিভাইসের জন্য: সেটিকে অ্যাসেট হিসেবে <strong>তৈরি</strong> করুন (এবং টুল যেখানে দেখেছে সেখানে সংযুক্ত করুন), বা উপেক্ষা করুন। সিদ্ধান্ত <em>সিদ্ধান্ত হয়েছে</em>-র অধীনে আবার খোলা যায়, আর যে কেস নিজে থেকে মিটে যায় তা নিজেই বন্ধ হয়।',
        'merge_body' => '<strong>মার্জ করলে সবকিছু থাকে।</strong> আপনি যে রেকর্ডটি রাখবেন তা বেছে নেন; অন্যটির সবকিছু সেটিতে চলে আসে - ইতিহাস, টিকিট, চুক্তি, নথি, প্রজেক্ট, লিজ, হেফাজত, সংযোগ, কাস্টম ফিল্ডের মান ও ইনভেন্টরি। দুটিতে একই জিনিস থাকলে আপনার রাখা রেকর্ডেরটিই থাকে, আর ফাঁকা ফিল্ড অন্যটি থেকে পূরণ হয়। অন্য রেকর্ডটি তখন সরে যায়, কিন্তু তার ছাপা QR লেবেল, তার লিঙ্ক এবং REST API দিয়ে তাকে রিপোর্ট করা টুলগুলো সবই আপনার রাখা রেকর্ডটি খুঁজে পায়। মার্জ পূর্বাবস্থায় ফেরানো যায় না, এবং শুধু ডিসকভারি ও রিকনসিলিয়েশন অনুমতি থাকা ব্যক্তিই মার্জ করতে পারেন।',
        'protect_heading' => 'যে সংশোধন টিকে থাকে',
        'protect_body' => 'এজেন্ট ও Intune প্রতিটি রিপোর্টে <strong>নাম</strong>, <strong>প্রস্তুতকারক</strong> ও <strong>মডেল</strong> লেখে, যা পরের সিঙ্কে &ldquo;Hewlett-Packard&rdquo;-এর মতো সংশোধন বাতিল করে দিত। এই ফিল্ডগুলোর একটির পাশের <strong>তালা</strong>-তে ক্লিক করে সেটি সুরক্ষিত করুন: কোনো রিপোর্টিং টুল তা ওভাররাইট করবে না, আর টুল ভিন্ন কিছু রিপোর্ট করলে তা ফিল্ডের নিচে দেখানো হয় (<em>এজেন্ট রিপোর্ট করেছে &ldquo;HP&rdquo;</em>) এবং <strong>ছাড়ুন</strong> দিয়ে টুলকে আবার জিতিয়ে দেওয়া যায়। টুল রিপোর্ট করে এমন অ্যাসেটে এই ফিল্ডগুলোর একটি সংশোধন করলে তা স্বয়ংক্রিয়ভাবে সুরক্ষিত হয় - এটি বন্ধ করতে <strong>সেটিংস &rarr; ডিসকভারি ও রিকনসিলিয়েশন</strong> দেখুন। সিরিয়াল নম্বর সুরক্ষিত করা যায় না, কারণ মেলানো এর উপর নির্ভর করে। মানুষ - এই পেজে, REST API দিয়ে বা ইমপোর্টে - সুরক্ষিত মানও বদলাতে পারে।',
        'names_heading' => 'প্রস্তুতকারক প্রতি একটি নাম',
        'names_body' => 'HP, HP Inc. এবং Hewlett-Packard একই প্রস্তুতকারক, কিন্তু প্রস্তুতকারক অনুযায়ী চার্টে তিনটি অংশ দেখায়। <strong>সেটিংস &rarr; ডিসকভারি ও রিকনসিলিয়েশন &rarr; প্রস্তুতকারক ও মডেলের নাম</strong>-এ প্রতিটি বানানের জন্য দেখানোর নাম বেছে নিন। টেবিল ভিউ, তার ফিল্টার, অ্যাসেট তালিকার অনুসন্ধান ও ড্যাশবোর্ড চার্ট আপনার বাছা নাম ব্যবহার করে; প্রতিটি অ্যাসেট রিপোর্ট করা মান রেখে দেয় (মূল তথ্যে নিচে <em>HP হিসেবে দেখানো হচ্ছে</em> লেখা থাকে), তাই একটি লাইন মুছলে তা বাতিল হয়। লেবেল, হস্তান্তর নথি ও অন্যান্য প্রিন্টআউটে সংরক্ষিত মান দেখায়।',
        'connected_heading' => 'কোনটি কীসের সাথে লাগানো',
        'connected_body' => '<strong>সংযুক্ত</strong> ট্যাব দেখায় একটি অ্যাসেটের সাথে ভৌতভাবে কী লাগানো আছে - কম্পিউটারে একটি মনিটর, ডকে একটি ফোন - এবং তা <strong>দুই প্রান্ত থেকেই</strong> দেখায়: মনিটরে কম্পিউটার তালিকাভুক্ত হয়, কম্পিউটারে মনিটর। নিজে একটি রেকর্ড করতে <strong>সংযোগ</strong> ব্যবহার করুন: অন্য অ্যাসেটটি নাম, সিরিয়াল বা অ্যাসেট ট্যাগ দিয়ে খুঁজুন। দুটিই একই কোম্পানিতে থাকতে হবে। REST API দিয়ে রিপোর্ট করা টুলও যা দেখে তা রেকর্ড করতে পারে, এবং তার সারিতে লেখা থাকে <em>সর্বশেষ lansweeper ৩ ঘণ্টা আগে সংযুক্ত দেখেছে</em> - মানে কখন শেষবার দেখেছে, এখন সংযুক্ত আছে তা নয়। <strong>নিশ্চিত করুন</strong> টুলের নিশ্চিতকরণের পাশে আপনার নিজের নিশ্চিতকরণ যোগ করে। প্রতিটি সংযোগ ও বিচ্ছিন্নকরণ দুই অ্যাসেটের ইতিহাসেই থাকে, এবং শেষ হওয়াগুলো <strong>আগের সংযোগ</strong>-এর অধীনে থাকে।',
        'connected_rules' => '<strong>প্রতিটি উৎসের নিজস্ব সারি থাকে।</strong> আপনি যা নিশ্চিত করেছেন এবং টুল যা দেখেছে তা পাশাপাশি থাকে, কেউ কাউকে ওভাররাইট করে না: টুল কখনও আপনার সংযোগ শেষ করে না, আর <strong>বিচ্ছিন্ন করুন</strong> শুধু কোনো ব্যক্তির নিশ্চিত করা সংযোগ শেষ করে। কোনো রিপোর্টে উল্লেখ না থাকলেই কিছু বিচ্ছিন্ন হয় না - যে টুল দেখেছিল শুধু সেই বলতে পারে এটি চলে গেছে। সংযোগ মানে হেফাজত নয় (কার কাছে আছে) এবং CMDB নির্ভরতাও নয়। একটি মনিটর একটি কম্পিউটারের সাথে সংযুক্ত এবং একজন ব্যক্তির নামে বরাদ্দ থাকতে পারে, একটি অন্যটিকে বদলায় না। অন্য যেকোনো ট্যাবের মতো এই ট্যাবও অ্যাসেটের ধরন অনুযায়ী লুকানো যায়।',
        'freshness_heading' => 'প্রতিটি তালিকা কতটা সতেজ?',
        'freshness_body' => '<strong>স্টোরেজ</strong>, <strong>ডিভাইস</strong> ও <strong>সফটওয়্যার</strong>-এর উপরে একটি লাইন বলে কোন টুল তালিকাটি রিপোর্ট করেছে এবং কখন দেখেছে: <em>এজেন্ট থেকে, ৩ ঘণ্টা আগে দেখা।</em> এটি <strong>সেটিংস &rarr; ডিসকভারি ও রিকনসিলিয়েশন &rarr; ইনভেন্টরি পুরোনো ধরা হয়</strong>-এর চেয়ে পুরোনো হলে (বদলাননি হলে ৭ দিন) <strong>হলুদ</strong> হয়ে যায়। শেষ রিপোর্টে বাদ পড়া তালিকা সেটি জানায়, আর যে সংগ্রহ <strong>ব্যর্থ</strong> হয়েছে তা ত্রুটিসহ লাল রঙে দেখায় - আগের তালিকা তার নিজের বয়সসহ রাখা হয়। মূল তথ্যের নিচের <strong>ইনভেন্টরি উৎস</strong> প্যানেল অ্যাসেটকে রিপোর্ট করা প্রতিটি টুল এবং তার রাখা প্রতিটি তালিকা দেখায়, আর কোনো ধরনের লেআউট তা লুকায় না। কোনো তালিকা কখনও রিপোর্ট না হলে তা বলা হয় এবং ট্যাবের সংখ্যায় ড্যাশ দেখায়, তাই <strong>০</strong> মানে সবসময় একটি টুল দেখেছে এবং কিছু পায়নি।',
        'freshness_agent' => '<strong>খালি রিপোর্ট করা</strong> এবং <strong>ব্যর্থ</strong> আসে ৩.১৫.০ এর সাথে আসা এজেন্ট স্ক্রিপ্ট থেকে। পুরোনো স্ক্রিপ্ট &ldquo;কিছু নেই&rdquo; আর &ldquo;দেখা যায়নি&rdquo; আলাদা করতে পারে না, তাই তার খালি তালিকা রিপোর্ট না হওয়া হিসেবে ধরা হয় এবং আগের তালিকা আগের মতোই থাকে। আপগ্রেডের আগে রিপোর্ট হওয়া অ্যাসেটে পরবর্তী রিপোর্ট পর্যন্ত কোনো লাইন দেখায় না।',
        'layout_heading' => 'অ্যাসেটের ধরনের সাথে মানানসই একটি পেজ',
        'layout_body' => 'প্রতিটি অ্যাসেটের ধরন ঠিক করে তার অ্যাসেটগুলো কোন বিল্ট-ইন বিবরণ ও ট্যাব দেখাবে। একটি মনিটরের CPU, মেমরি বা ডিভাইস ট্যাব লাগে না, তাই তার ধরন সেগুলো লুকাতে পারে, আর ট্যাবগুলো তার উপযোগী ক্রমে সাজানো যায়। এটি ঠিক করুন <strong>সেটিংস &rarr; অ্যাসেটের ধরন</strong>-এ: একটি ধরন সম্পাদনা করে <strong>লেআউট</strong> ব্যবহার করুন, অথবা একটি শুরুর বিন্দু (পেরিফেরাল, নেটওয়ার্ক সরঞ্জাম, মোবাইল ডিভাইস) বেছে টিকগুলো ঠিক করুন। নাম, অ্যাসেট ট্যাগ, সিরিয়াল নম্বর, ধরন, স্ট্যাটাস, অবস্থান ও কোম্পানি সবসময় দেখায়, এবং মূল তথ্য সবসময় প্রথমে থাকে।',
        'layout_hidden' => '<strong>লুকানো শুধু পেজের ব্যাপার।</strong> কিছুই মুছে যায় না, এজেন্ট ও ইমপোর্ট প্রতিটি ফিল্ড রেকর্ড করতে থাকে, আর টেবিল ভিউ ও API এখনও সবকিছু দেখায়। কোনো অ্যাসেটে তার ধরনের লুকানো বিবরণ থাকলে - ধরুন ভুল ধরনের কম্পিউটার - মূল তথ্য তা জানায় (<em>এই ধরনের লেআউট দ্বারা লুকানো: সফটওয়্যার (214)</em>) এবং <strong>দেখান</strong> দেয়, যা ওই অ্যাসেটের জন্য প্রতিটি লুকানো সেকশন ও ট্যাব ড্যাশ-দাগ রেখাসহ ফিরিয়ে আনে। <strong>সেটিংস &rarr; অ্যাসেটের ধরন &rarr; যে বিবরণ একটি ধরন লুকায়</strong> তা বদলে একটি শান্ত <em>লুকানো দেখান</em> লিঙ্ক করতে পারে।',
        'proxmox' => [
            'nav' => 'Proxmox VE সার্ভার',
            'heading' => 'Proxmox VE সার্ভার',
            'intro' => 'FreeITSM এক বা একাধিক Proxmox VE সার্ভার থেকে ভার্চুয়াল মেশিন ও LXC কনটেইনার, নোড, IP ও MAC ঠিকানা পড়ে vCenter-এর পাশে <strong>সার্ভার</strong>-এর অধীনে তালিকাভুক্ত করতে পারে। এটি শুধু পড়ে: Proxmox-এ কখনোই কিছু পরিবর্তন করা হয় না। সার্ভার যোগ করুন <strong>সেটিংস &rarr; Proxmox VE সার্ভার</strong>-এ; প্রতিটি নিজস্ব সময়সূচিতে সিঙ্ক হয়।',
            'user_heading' => '১. FreeITSM-এর জন্য একটি ব্যবহারকারী ও রিড-অনলি ভূমিকা',
            'user_1' => 'Proxmox-এ <strong>Datacenter &rarr; Permissions &rarr; Users &rarr; Add</strong>: <code>freeitsm</code>-এর মতো একটি ব্যবহারকারী, <strong>Proxmox VE authentication server</strong> (<code>pve</code>) রেলমে। পাসওয়ার্ড লাগে না - এটি শুধু API টোকেন ধারণ করে।',
            'user_2' => '<strong>Datacenter &rarr; Permissions &rarr; Roles &rarr; Create</strong> করে <code>FreeITSMSync</code>-এর মতো একটি ভূমিকা তৈরি করুন, যাতে থাকবে <code>Sys.Audit</code>, <code>VM.Audit</code> ও <code>Datastore.Audit</code>, এবং গেস্টের IP ঠিকানার জন্য Proxmox VE 9-এ <code>VM.GuestAgent.Audit</code> বা Proxmox VE 8-এ <code>VM.Monitor</code> (সংস্করণ ৯ এটির জায়গায় এসেছে)।',
            'user_3' => '<strong>Datacenter &rarr; Permissions &rarr; Add &rarr; User Permission</strong>: পাথ <code>/</code>, ব্যবহারকারী এবং ভূমিকা।',
            'token_heading' => '২. একটি API টোকেন (প্রস্তাবিত)',
            'token_1' => '<strong>Datacenter &rarr; Permissions &rarr; API Tokens &rarr; Add</strong>, ওই ব্যবহারকারীর জন্য, <code>itsm</code>-এর মতো একটি Token ID দিয়ে।',
            'token_2' => '<strong>Privilege Separation</strong>-এর টিক তুলে দিন যাতে টোকেন ব্যবহারকারীর অনুমতিগুলো পায় - অথবা টিক রেখে ধাপ ১-এর মতো ভূমিকাটি টোকেনকেই দিন।',
            'token_3' => 'Proxmox <strong>secret</strong> একবারই দেখায়। এখনই কপি করুন; হারিয়ে গেলে টোকেনটি মুছে নতুন একটি বানান।',
            'fill_heading' => '৩. FreeITSM-এ সার্ভার যোগ করুন',
            'fill_host' => '<strong>সার্ভারের ঠিকানা</strong>: <code>https://pve.example.com:8006</code>। শুধু https গ্রহণ করা হয়, কারণ প্রতিটি অনুরোধের সাথে secret যায়।',
            'fill_user' => '<strong>ব্যবহারকারী বা API টোকেন</strong>: টোকেন ID, <code>freeitsm@pve!itsm</code> - ব্যবহারকারী, রেলম, <code>!</code>, টোকেন ID। <code>freeitsm@pve</code>-এর মতো সাধারণ ব্যবহারকারীও চলে, তার পাসওয়ার্ড সহ।',
            'fill_secret' => '<strong>পাসওয়ার্ড</strong>: টোকেনের secret (অথবা ব্যবহারকারীর পাসওয়ার্ড)। এটি এনক্রিপ্ট করে রাখা হয় এবং আর কখনো দেখানো হয় না; সম্পাদনার সময় বহাল রাখতে খালি রাখুন।',
            'fill_verify' => '<strong>সার্টিফিকেট যাচাই</strong>: বিশ্বস্ত কর্তৃপক্ষের সার্টিফিকেটের জন্য টিক রাখুন। Proxmox নিজের সেলফ-সাইন্ড সার্টিফিকেট নিয়ে ইনস্টল হয়; সেক্ষেত্রে টিক তুলে দিন, অথবা আরও ভালো হয় Proxmox-কে একটি বিশ্বস্ত সার্টিফিকেট দিলে।',
            'fill_interval' => '<strong>সিঙ্কের ব্যবধান</strong>: নির্ধারিত সিঙ্কের মধ্যে কত মিনিট, যা <code>cron/proxmox_sync.php</code> চালায়।',
            'test' => '<strong>পরীক্ষা</strong> ক্লিক করুন, তারপর <strong>এখনই সিঙ্ক</strong> ও <strong>VM দেখান</strong>।',
            'ips_heading' => 'IP ঠিকানা',
            'ips' => 'Proxmox একটি VM-এর IP ঠিকানা জানে শুধু QEMU গেস্ট এজেন্টের মাধ্যমে: VM-এর <strong>Options</strong>-এ এটি চালু করুন এবং গেস্টে <code>qemu-guest-agent</code> ইনস্টল করুন। শুধু VM-এর নিজস্ব নেটওয়ার্ক কার্ডের ঠিকানাগুলো রাখা হয়, তাই ভেতরের Docker ও ব্রিজ ইন্টারফেস বাদ যায়। কনটেইনারের ঠিকানা আসে তার কনফিগারেশন থেকে; DHCP ঠিকানা জানা যায় না।',
            'removal_heading' => 'কোনো VM তালিকা থেকে অদৃশ্য হলে',
            'removal' => 'সফলভাবে পড়া কোনো তালিকায় VM আর না থাকলেই কেবল সেটি সরানো হয়। কোনো নোড অফলাইন থাকলে, বা তার VM বা কনটেইনারের তালিকা পড়া না গেলে, তার VM-গুলো রাখা হয়। আর FreeITSM-এর জানা VM-এর অর্ধেকের কম দেখা গেলে, একটি সুস্থ সিঙ্ক নিশ্চিত না করা পর্যন্ত কিছুই সরানো হয় না (<strong>নিরাপত্তা প্রহরী</strong>)।',
            'trouble_heading' => 'কিছু ভুল হলে',
            'trouble_401' => '<strong>প্রত্যাখ্যাত (HTTP 401 বা 403)</strong>: টোকেন ID বা secret ভুল, অথবা এর কোনো অনুমতি নেই। রেলম <code>pve</code> কিনা দেখুন, <code>pam</code> নয়।',
            'trouble_reach' => '<strong>Proxmox সার্ভারে পৌঁছানো যায়নি</strong>: ঠিকানা বা পোর্ট (সাধারণত 8006) ভুল, অথবা ফায়ারওয়াল বাধা দিচ্ছে।',
            'trouble_cert' => 'সার্টিফিকেট যাচাই টিক থাকা অবস্থায় <strong>সার্টিফিকেট ত্রুটি</strong>: Proxmox তার সেলফ-সাইন্ড সার্টিফিকেট ব্যবহার করছে। টিক তুলে দিন, অথবা Proxmox-এ একটি বিশ্বস্ত সার্টিফিকেট ইনস্টল করুন।',
            'trouble_node' => '<strong>এই চক্রে পৌঁছানো যায়নি: একটি নোডের নাম</strong>: ওই নোড বা তার তালিকা সাড়া দেয়নি। তার VM-গুলো রাখা হয়েছে।',
            'trouble_guard' => '<strong>নিরাপত্তা প্রহরী</strong>: জানা VM-এর অর্ধেকের কম দেখা গেছে এবং কিছুই মোছা হয়নি। সাধারণত এটি অনুমতির সমস্যা বা অফলাইন নোড, প্রকৃত মুছে ফেলা নয়।',
            'more' => 'সম্পূর্ণ নির্দেশিকা উইকিতে আছে: <a href="https://github.com/edmozley/freeitsm/wiki/Proxmox-VE" target="_blank" rel="noopener">Proxmox VE</a>।',
