            'user_2' => 'প্রতিটি অর্গানাইজেশনের জন্য: একটি প্রোভাইডার অ্যাডমিনিস্ট্রেটর, অর্গানাইজেশন <code>System</code> সহ।',
            'fill_heading' => '২. FreeITSM-এ সার্ভার যোগ করুন',
