            'fill_org' => '<strong>অর্গানাইজেশন</strong>: এর <em>নাম</em> - সাইন ইন করার সময় ঠিকানায় যেটি থাকে (<code>/tenant/acme</code> মানে <code>acme</code>) - প্রদর্শন নাম নয়। প্রোভাইডার অ্যাডমিনিস্ট্রেটরের জন্য <code>System</code>।',
            'fill_user' => '<strong>ব্যবহারকারী</strong> ও <strong>পাসওয়ার্ড</strong>: ধাপ ১-এর ব্যবহারকারী, <code>@organization</code> ছাড়া। পাসওয়ার্ড এনক্রিপ্ট করে রাখা হয় এবং আর কখনো দেখানো হয় না।',
            'fill_version' => '<strong>API সংস্করণ</strong>: Cloud Director 10.5-এর জন্য <code>38.0</code>, 10.3-এর জন্য <code>36.2</code>। সার্ভার যে সংস্করণ দেয় না তা পরীক্ষার সময় স্পষ্টভাবে ব্যর্থ হয়।',
            'fill_verify' => '<strong>সার্টিফিকেট যাচাই</strong>: পোর্টাল সেলফ-সাইন্ড সার্টিফিকেট ব্যবহার না করলে টিক রাখুন।',
            'test' => '<strong>পরীক্ষা</strong> ক্লিক করুন, তারপর <strong>এখনই সিঙ্ক</strong> ও <strong>VM দেখান</strong>, যা এজ গেটওয়েগুলোও তালিকাভুক্ত করে।',
            'removal_heading' => 'কোনো VM তালিকা থেকে অদৃশ্য হলে',
            'removal' => 'শুধু পুরো VM তালিকা, তার প্রতিটি পাতা, পড়া হওয়ার পরেই। কোনো পাতা ব্যর্থ হলে সেবার কিছুই সরানো হয় না। একই নিরাপত্তা প্রহরী প্রযোজ্য: জানা VM-এর অর্ধেকের কম দেখা গেলে কিছুই সরানো হয় না। এজ গেটওয়েও সরানো হয় শুধু তাদের সব পাতা পড়া হওয়ার পরে।',
