            'trouble_reach' => '<strong>vCloud Director সার্ভারে পৌঁছানো যায়নি</strong>: ঠিকানা ভুল, অথবা ফায়ারওয়াল বাধা দিচ্ছে।',
            'trouble_partial' => '<strong>আংশিক পড়া গেছে</strong>: VM তালিকার একটি পাতা ব্যর্থ হয়েছে। কিছুই সরানো হয়নি; পরবর্তী সিঙ্ক আবার চেষ্টা করবে।',
            'trouble_guard' => '<strong>নিরাপত্তা প্রহরী</strong>: জানা VM-এর অর্ধেকের কম দেখা গেছে এবং কিছুই মোছা হয়নি। সাধারণত ব্যবহারকারী অধিকার হারিয়েছে, অথবা অর্গানাইজেশন বদলেছে।',
