        'companies' => [
            'nav' => 'অ্যাসেট ও কোম্পানি',
            'heading' => 'অ্যাসেট ও কোম্পানি',
            'intro' => 'একাধিক কোম্পানির দেখাশোনা করে এমন ইনস্টলে প্রতিটি অ্যাসেট একটি কোম্পানির অন্তর্গত। <em>আপনি যদি একটিমাত্র কোম্পানির জন্য FreeITSM চালান, তবে এই অংশ প্রযোজ্য নয়।</em>',
            'move' => '<strong>অ্যাসেট সরানো</strong> &mdash; <strong>মূল তথ্য</strong>-তে অ্যাসেট ট্যাগের পাশের <strong>কোম্পানি</strong> ফিল্ড বদলে নিশ্চিত করুন। আপনি শুধু সেই কোম্পানিতেই অ্যাসেট সরাতে পারবেন যেটিতে আপনার নিজের প্রবেশাধিকার আছে, এবং সরানোটি তার ইতিহাসে লেখা থাকে।',
            'cleared' => '<strong>কী মুছে যায়</strong> &mdash; যা শুধু পুরোনো কোম্পানির: তার অবস্থান (অবস্থানটি শেয়ার করা না হলে), এবং পুরোনো কোম্পানি নিজের জন্য যোগ করা ধরন বা স্ট্যাটাস। সরানোর পরের বার্তায় কী মুছেছে তা বলা থাকে। ইতিহাস, কাস্টম ফিল্ড, নথি এবং যে বিশ্লেষক এটি ধারণ করেন তিনি এর সাথে চলে যান।',
            'refused' => '<strong>সরানো প্রত্যাখ্যাত হলে</strong> &mdash; নতুন কোম্পানিতে একই নাম বা অ্যাসেট ট্যাগের অ্যাসেট আগে থেকেই থাকলে, অথবা অ্যাসেটটি অন্য কোম্পানির কোনো ব্যক্তির কাছে থাকলে। বার্তায় কোনটি তা বলা থাকে, যাতে আপনি ঠিক করে আবার চেষ্টা করতে পারেন।',
            'add' => '<strong>অ্যাসেট যোগ করা</strong> &mdash; আপনার একাধিক কোম্পানিতে প্রবেশাধিকার থাকলে <strong>অ্যাসেট যোগ</strong> জিজ্ঞাসা করে এটি কোনটির জন্য, এবং ধরন, স্ট্যাটাস ও অবস্থানের তালিকা আপনার পছন্দ অনুসরণ করে। <strong>সব কোম্পানি</strong> ভিউতে কোনো ডিফল্ট নেই, তাই নতুন অ্যাসেট আপনার সর্বশেষ বেছে নেওয়া কোম্পানিতে গিয়ে পড়তে পারে না।',
            'shared' => '<strong>শেয়ার করা অবস্থান</strong> &mdash; <strong>সেটিংস &rarr; অবস্থান</strong>-এ, সব কোম্পানিতে প্রবেশাধিকার আছে এমন কেউ একটি অবস্থানকে <strong>প্রতিটি কোম্পানির সাথে শেয়ার করা</strong> চিহ্নিত করতে পারেন, যেমন একাধিক ক্লায়েন্টের ব্যবহৃত ডেটা সেন্টার। তখন প্রতিটি কোম্পানি নিজেদের অবস্থানের পাশাপাশি এটিও বেছে নিতে পারে। অন্য কোম্পানির অ্যাসেট এখনো সেখানে থাকলে শেয়ার করা অবস্থানের শেয়ারিং বন্ধ করা যায় না।',
            'note' => '<strong>সব কোম্পানি</strong> ভিউতেও অ্যাসেট তালিকা একবারে একটি কোম্পানিই দেখায়। সরানো অ্যাসেট আপনার দেখা তালিকা থেকে চলে যায় &mdash; এটি দেখতে তার নতুন কোম্পানিতে যান।',
            'recon' => '<strong>হার্ডওয়্যার ডিসকভারি ও রিকনসিলিয়েশন</strong> &mdash; স্বয়ংক্রিয় ইনভেন্টরি রিপোর্ট (PowerShell এজেন্ট বা Microsoft Intune থেকে) শুধু লক্ষ্য কোম্পানির ভেতরেই অ্যাসেট মেলায়। বিভিন্ন কোম্পানিতে একই সিরিয়াল নম্বর বা হোস্টনেম সম্পূর্ণ আলাদা থাকে এবং কখনো সীমানা অতিক্রম করে না।',
