            'intro' => 'A4 শিটে বা লেবেল প্রিন্টারের টেপ বা রোলে অ্যাসেট লেবেল প্রিন্ট করুন, লেবেলের ঠিক মাপের PDF হিসেবে - অথবা পেশাদার প্রিন্ট হাউসের জন্য অ্যাসেট ডেটা এক্সপোর্ট করুন।',
            'fields_strong' => 'কনফিগারযোগ্য ফিল্ড নির্বাচন',
            'fields_text' => '<strong>সেটিংস &rarr; অ্যাসেট লেবেল ও QR</strong>-এ কোন ফিল্ড কী ক্রমে দেখাবে তা বেছে নিন - হোস্টনেম, সিরিয়াল, মডেল, অবস্থান, ফাইন্যান্স ID-এর মতো আপনার নিজের কাস্টম ফিল্ড - সাথে হেডার, ফুটার এবং প্রতিটি ফিল্ডের নাম প্রিন্ট হবে কিনা। অ্যাসেট ট্যাগ সবসময় লেবেলে থাকে।',
            'qr_strong' => 'QR কোড ও একটি লোগো',
            'qr_text' => 'QR কোড ইনস্টলের পাবলিক ঠিকানা ব্যবহার করে FreeITSM-এ অ্যাসেটটি খোলে। এর মাঝখানে আপনার লোগো বসাতে পারেন; তখন কোডটি বেশি বিল্ট-ইন রিডান্ড্যান্সি সহ প্রিন্ট হয় যাতে স্ক্যান করা যায়। পুরো ব্যাচ প্রিন্টের আগে একটি সবচেয়ে ছোট আকারে প্রিন্ট করে সাধারণ ফোন দিয়ে স্ক্যান করে দেখুন।',
            'designs_strong' => 'লেবেল ডিজাইন',
            'designs_text' => '<strong>সেটিংস &rarr; অ্যাসেট লেবেল ও QR &rarr; লেবেল ডিজাইন</strong>-এ একাধিক ডিজাইন রাখুন - প্রতিটি একটি লেবেল আকারের উপর একটি লেআউট - এবং <strong>লেবেল প্রিন্ট</strong> যেটি ব্যবহার করবে সেটি বেছে নিন। লেআউটগুলো: <em>Standard</em> (লেবেল যেমন বরাবর দেখাত), <em>Logo left, details middle, QR right</em> (আপনার লোগো বড়, টেপ লেবেলের জন্য), <em>Small</em> (QR ও ট্যাগ) এবং <em>Large</em> (লোগো, QR, তারপর বিবরণ)। এগুলো ট্যাবের নিচে ঠিক করা হেডার, ফুটার, ফিল্ড ও লোগো ব্যবহার করে। প্রিন্ট পেজে একটি প্রিন্টের জন্য অন্য ডিজাইন বা আকার বেছে নিতে পারেন।',
            'designer_strong' => 'লেবেল ডিজাইনার',
            'designer_text' => 'স্লাইডের মতো নিজে লেবেল সাজাতে ডিজাইনের পাশের <strong>ডিজাইন</strong> চাপুন: টুলবক্স থেকে টেক্সট, ফিল্ড, ফিল্ড তালিকা, QR কোড, আপনার লোগো, লাইন ও বক্স টেনে আনুন, তারপর সরান ও আকার বদলান - এগুলো লেবেলের কিনারা ও কেন্দ্রে এবং একে অপরের সাথে স্ন্যাপ করে। লেবেল একটি আসল অ্যাসেটের মান দেখায়, আর <em>লম্বা মানসহ নমুনা</em> সবচেয়ে খারাপ অবস্থা দেখায়; প্রতিটি টেক্সট ঠিক করে লম্বা মান ছোট হবে, ভাঙবে নাকি কেটে যাবে। সাজান জিনিসগুলো সারিবদ্ধ করে, অ্যারো কী সামান্য সরায়, এবং Ctrl+Z আনডু করে। ডিজাইনারে একবার সংরক্ষণ করলে ডিজাইন আপনার সাজানো ঠিক তা-ই রাখে এবং ট্যাবের নিচে ঠিক করা হেডার, ফুটার ও ফিল্ড আর অনুসরণ করে না।',
            'sizes_strong' => 'লেবেলের আকার ও প্রিন্টিং',
            'sizes_text' => 'Brother TZe ও DK টেপ, Dymo লেবেল, চারটি A4 শিট, অথবা আপনার নিজের মাপ। <strong>ডাউনলোড</strong> লেবেলের ঠিক মাপে একটি PDF বানায় - টেপ বা রোল প্রিন্টারের জন্য প্রতি পেজে একটি লেবেল। এটি প্রিন্টারের নিজস্ব ড্রাইভার দিয়ে <strong>আসল আকারে</strong> প্রিন্ট করুন (কখনও "Fit to page" নয়)। শিটের ক্ষেত্রে, আপনার লেবেল সামান্য সরে প্রিন্ট হলে ১০ মিমি পর্যন্ত প্রিন্টার অফসেট প্রতিটি লেবেল সরায়। টেপ বা রোল প্রিন্টারের ডিজাইন নিরেট কালোতে প্রিন্ট হয় - টেক্সট, লাইন ও সাদা-কালো লোগো - কারণ ওই প্রিন্টার ধূসরকে বিন্দু দিয়ে প্রিন্ট করে যা পড়া কঠিন। রঙিন লেবেলের জন্য ডিজাইনে <strong>শুধু-কালো প্রিন্টার</strong>-এর টিক তুলে দিন।',
            'fonts_strong' => 'ফন্ট ও অন্যান্য ভাষা',
            'fonts_text' => 'লেবেল Noto Sans ব্যবহার করে, এবং এতে যে অক্ষর নেই তা কম্পিউটারের নিজস্ব ফন্ট আঁকে, তাই যেকোনো ভাষার নাম প্রিন্ট হয়। <strong>লেবেল ফন্ট</strong>-এর অধীনে একটি ফন্ট আপলোড করুন - আপনার ব্র্যান্ডের ফন্ট, বা কোনো ভাষার জন্য - এবং ডিজাইনে সেটি বেছে নিন। ডিজাইন ব্যবহার করছে এমন ফন্ট মুছে ফেলা যায় না।',
        ],
