        'nav_users' => 'কার কাছে কী আছে',
        'nav_tips' => 'দ্রুত টিপস',
        'users_heading' => 'কার কাছে কী আছে',
        'users_intro' => '<strong>ব্যবহারকারী</strong> ট্যাব এমন একটি প্রশ্নের উত্তর দেয় যার জন্য আগে অ্যাসেট তালিকা একটি একটি করে খুঁজতে হতো: এই ব্যক্তির কাছে আসলে কী আছে? কাউকে বেছে নিন, তাঁর নামে বরাদ্দ সবকিছু এক স্ক্রিনে দেখা যায়, এবং তাঁর সইয়ের জন্য একটি হস্তান্তর নথি প্রিন্ট করতে পারেন।',
        'users_step1_strong' => 'ব্যক্তিকে খুঁজুন।',
        'users_step1_list' => 'বাম দিকের তালিকায় আপনার বর্তমান ব্যক্তিরা দেখা যায়, প্রত্যেকের কাছে কতটি আছে তার সংখ্যা সহ। নাম, ইমেল বা বিভাগ দিয়ে অনুসন্ধান করুন, এবং <strong>চলে যাওয়া</strong>, <strong>সবাই</strong> বা শুধু <strong>সরঞ্জাম আছে এমন</strong> বাছতে প্রথম ড্রপডাউন ব্যবহার করুন। যেখানে ব্যক্তিরা ডিরেক্টরি বা অ্যাড্রেস বুক থেকে আসে, সেখানে দ্বিতীয় ড্রপডাউন <strong>উৎস</strong> শুধু তাদের কোনো একটি থেকে আসা ব্যক্তিদের, বা শুধু FreeITSM-এ যোগ করা ব্যক্তিদের তালিকাভুক্ত করে; তাদের বিবরণে উৎসের নাম থাকে। কোনো অ্যাড্রেস বুকে নেই এমন কাউকে <strong>অ্যাড্রেস বুকে যোগ</strong> দিয়ে একটিতে যোগ করা যায়, যদি অ্যাডমিনিস্ট্রেটর ওই অ্যাড্রেস বুকের জন্য অনুমতি দিয়ে থাকেন।',
        'users_step2_strong' => 'তাঁর কাছে কী আছে দেখুন।',
        'users_step2_text' => 'কোনো ব্যক্তিতে ক্লিক করলে তাঁর নামে বরাদ্দ প্রতিটি আইটেম দেখা যায়, ধরন, নাম, তৈরিকারী ও মডেল, সিরিয়াল নম্বর, অ্যাসেট ট্যাগ এবং বরাদ্দের তারিখ সহ &mdash; অডিট বা অফবোর্ডিং পরীক্ষার ঠিক এটিই দরকার।',
        'users_step3_strong' => 'হস্তান্তর নথি প্রিন্ট বা ইমেল করুন।',
        'users_step3_text' => '<strong>হস্তান্তর নথি</strong> বোতাম একটি রেকর্ড তৈরি করে যাতে ব্যক্তি, তাঁর সরঞ্জাম ও বরাদ্দের তারিখ তালিকাভুক্ত থাকে, সাথে একটি ঘোষণা এবং তাঁর ও IT-এর উভয়ের সইয়ের জায়গা। এটি প্রিন্ট করুন, ইলেকট্রনিক কপির জন্য ব্রাউজারের <strong>Save as PDF</strong> ব্যবহার করুন, অথবা সরাসরি ব্যক্তিকে পাঠাতে <strong>তাঁকে ইমেল করুন</strong>। <strong>সিস্টেম &rarr; ব্র্যান্ডিং</strong>-এ আপনার কোম্পানির লোগো দেওয়া থাকলে সেটি এতে দেখা যায়।',
        'users_step4_strong' => 'নথিতে কী লেখা থাকবে বদলান।',
        'users_step4_text' => '<strong>সেটিংস &rarr; হস্তান্তর নথি</strong> দিয়ে এর বিন্যাস ঠিক করা যায়: অংশ চালু বা বন্ধ করা, ক্রম বদলানো, শব্দ বদলানো, এবং সরঞ্জামের টেবিলে কোন কলাম দেখাবে বাছা &mdash; আপনার নিজের কাস্টম ফিল্ডও সহ, যাতে একটি মনিটরের সাইজ ও রেজোলিউশন সহ কাগজে সই হয়। কাস্টম কলাম আপনি চালু না করা পর্যন্ত বন্ধ থাকে, কারণ হস্তান্তর এমন একটি রেকর্ড যাতে কেউ সই করে। <code>{{employee.name}}</code>-এর মতো মার্জ কোড নথি তৈরির সময় নিজেই পূরণ হয়, এবং লাইভ প্রিভিউ আপনি লেখার সাথে সাথে ফলাফল দেখায়।',
        'users_step5_strong' => 'তাঁর তথ্য হালনাগাদ রাখুন।',
        'users_step5_text' => '<strong>সম্পাদনা</strong> ব্যক্তি সম্পাদকটি খোলে &mdash; টিকিট &rarr; ব্যবহারকারী যেটি খোলে ঠিক সেটিই, তাই নাম, যোগাযোগের তথ্য, কোম্পানি, ম্যানেজার ও পাসওয়ার্ড যেখানেই থাকুন একইভাবে বদলানো যায়। ম্যানেজারের জন্য নামের একটি অংশ লিখে তাঁকে খুঁজুন। <strong>চলে গেছেন চিহ্নিত করুন</strong> ব্যক্তি ও তাঁর কাছে থাকা সবকিছু রেকর্ডে রেখে বর্তমান তালিকা থেকে সরিয়ে দেয়; <strong>পুনরায় সক্রিয়</strong> তাঁকে ফিরিয়ে আনে। যেখানে কোনো ব্যক্তি ডিরেক্টরি বা অ্যাড্রেস বুক থেকে আসে, সেখানে সেটির মালিকানাধীন তথ্য ধূসর থাকে।',
        'users_managers' => '<strong>ম্যানেজার।</strong> কেউ মানুষদের ম্যানেজ করলে তাঁর বিবরণে কারা তাঁকে রিপোর্ট করে তা তালিকাভুক্ত থাকে। <strong>ম্যানেজার অ্যাক্সেস</strong> একটি পূর্ণ-স্ক্রিন পাতা খোলে যাতে সেল্ফ-সার্ভিস পোর্টালে ওই ব্যক্তি কাদের টিকিট দেখতে পারেন তা দেখানো হয়, এবং আপনি তাঁর দলে ব্যক্তি, গ্রুপ বা বিভাগ যোগ বা বাদ দিতে পারেন; তিনি যে কাউকে দেখতে পান তাতে ক্লিক করলে কারণ জানা যায়। অ্যাডমিনিস্ট্রেটর <strong>সিস্টেম &rarr; ম্যানেজার</strong>-এ ম্যানেজার চালু করার পরেই কেবল এর প্রভাব পড়ে।',
        'users_tip' => 'সরঞ্জাম বরাদ্দ হয় অ্যাসেটেই, ব্যক্তির নামে, তাই কেউ এই তালিকায় না থাকলে বা কোনো আইটেম ভুল মনে হলে অ্যাসেটটি খুলে তার বরাদ্দকৃত ব্যবহারকারী দেখুন।',
        'overview_intro' => 'অ্যাসেট ব্যবস্থাপনা আপনাকে আপনার IT এস্টেটের একটি সম্পূর্ণ ইনভেন্টরি দেয়। Windows মেশিনগুলি একটি PowerShell স্ক্রিপ্ট ব্যবহার করে স্বয়ংক্রিয়ভাবে রিপোর্ট করে, এবং VMware ভার্চুয়াল মেশিনগুলি vCenter থেকে সিঙ্ক হয়। সবকিছু এক জায়গায় চলে আসে যেখানে আপনি অনুসন্ধান করতে, ব্যবহারকারী বরাদ্দ করতে, এবং ড্যাশবোর্ড তৈরি করতে পারেন।',
        'card_assets_title' => 'অ্যাসেট',
        'card_assets_desc' => 'প্রতিটি আবিষ্কৃত মেশিন ব্রাউজ ও অনুসন্ধান করুন। যেকোনো অ্যাসেটে ক্লিক করে এর হার্ডওয়্যার, স্টোরেজ, ডিভাইস, এবং ইনস্টল করা সফটওয়্যার এক নজরে দেখুন।',
        'card_dashboard_title' => 'ড্যাশবোর্ড',
        'card_dashboard_desc' => '১৩+ চার্টের ধরন থেকে আপনার নিজস্ব ড্যাশবোর্ড তৈরি করুন &mdash; OS বণ্টন, প্রস্তুতকারক বিভাজন, মেমরি স্তর, এবং আরও অনেক কিছু। প্রতিটি বিশ্লেষকের নিজস্ব লেআউট রয়েছে।',
        'card_servers_title' => 'সার্ভার',
        'card_servers_desc' => 'VMware vCenter-এর সাথে সংযোগ করুন এবং আপনার সম্পূর্ণ ভার্চুয়াল এস্টেট সিঙ্ক করুন। VM বিস্তারিত, হোস্ট প্লেসমেন্ট, স্টোরেজ, এবং নেটওয়ার্ক কনফিগারেশন দেখুন।',
        'card_assignment_title' => 'ব্যবহারকারী বরাদ্দ',
        'card_assignment_desc' => 'অ্যাসেটে ব্যবহারকারী বরাদ্দ করুন যাতে আপনি সর্বদা জানেন কার কাছে কোন ডিভাইস আছে। পুনঃবরাদ্দগুলি অডিট ট্রেইলে লগ করা হয়।',
        'locations_lead' => 'লোকেশন কোথায়?',
        'locations_body' => 'লোকেশন এখন <strong>সিস্টেম &rarr; লোকেশন</strong>-এ রাখা হয়, কারণ ফর্ম (এবং সময়ে ব্যক্তি ও টিকিট) এগুলো অ্যাসেটের পাশাপাশি ব্যবহার করে। এটি একই তালিকা, এবং প্রতিটি অ্যাসেট তার লোকেশন রেখেছে। এখানকার <strong>সেটিংস &rarr; লোকেশন</strong> এখনও একই ট্রি দেখায় ও সম্পাদনা করে, তাই অ্যাডমিন নন এমন অ্যাসেট ম্যানেজাররা আগের মতোই এটি দেখাশোনা করতে পারেন - যেকোনো এক জায়গায় পরিবর্তন করলে দুটিতেই দেখায়।',
        'inventory_script_heading' => 'ইনভেন্টরি স্ক্রিপ্ট',
    ],
    'leases' => [
        'settings_tab' => 'লিজিং',
        'outcomes_heading' => 'লিজের পরিণতি',
        'outcomes_intro' => 'একটি লিজ করা অ্যাসেটের কী পরিণতি হতে পারে। "এখনও লিজে" পরিণতিগুলো ফেরত দেওয়ার তালিকায় গণনা হয়; "শেষ হয়েছে" গুলো হয় না। সব কোম্পানির জন্য একটিই তালিকা।',
