        'empty_text' => 'লিজ হলো আপনার লিজিং কোম্পানির সাথে চুক্তি। একটি যোগ করুন, তারিখসহ একটি সময়সূচি দিন, তারপর লিজ করা অ্যাসেটগুলো এতে রাখুন। প্রতিটি অ্যাসেটের লিজের তারিখ সময়সূচি অনুসরণ করে, আর ফেরত দেওয়ার তালিকা দেখায় কী কখন ফেরত দিতে হবে।',
