        'h_delivery_created' => 'বুক ইন করা হয়েছে',
        'help_p8' => '<strong>ডেলিভারি।</strong> একটি অর্ডার মানে একটি ডেলিভারি: <strong>ডেলিভারি → নতুন</strong> সরবরাহকারী, একটি <strong>অর্ডার নম্বর</strong> (ঐচ্ছিক), ইনভয়েস নম্বর ও তারিখ, এবং প্রতিটি আইটেমের জন্য একটি লাইন নেয় - এক অর্ডারে ১০টি মাউস, ১০টি টোনার ও ৫টি কীবোর্ড। বুক ইন করলে প্রতিটি লাইন গ্রহণ করা হয়। ডেলিভারির পৃষ্ঠায় এর <strong>নথি</strong> (অর্ডার নিশ্চিতকরণ, ইনভয়েস) থাকে, বিবরণ সংশোধন করা যায় - প্রতিটি পরিবর্তন রেকর্ড হয় - এবং দুইবার বুক ইন হয়ে গেলে <strong>ডেলিভারি আনডু</strong> করা যায়। কোনো আইটেমে একটি <strong>গ্রহণ</strong> একটি এক-লাইনের ডেলিভারি তৈরি করে, ফলে প্রতিটি গ্রহণের কাগজপত্রের একটি ঠিকানা থাকে।',
        'help_heading' => 'কনজিউমেবল',
        'help_intro' => '<strong>কনজিউমেবল</strong> (হেডারে) হলো যেসব জিনিস একটি একটি করে ট্র্যাক না করে গণনা করা হয় - টোনার, ফিউজার, কাগজ, মাউস, কীবোর্ড, RAM। নিয়মটি হলো: যদি এর সিরিয়াল নম্বর লিখে রাখতেন তাহলে এটি অ্যাসেট; যদি গণনা করতেন তাহলে এটি কনজিউমেবল। স্টক সেই কোম্পানির, যেখানে আপনি কাজ করছেন।',
