        'help_step6' => '৬. তাকের জিনিস গণনা করুন',
        'help_step7' => '৭. কী হারিয়েছে দেখুন',
        'help_p1' => '<strong>আইটেম ও ধরন।</strong> <strong>নতুন</strong> একটি আইটেম যোগ করে: এর ধরন, পার্ট নম্বর, একক, সরবরাহকারী, একক খরচ, <strong>পুনরায় অর্ডারের স্তর</strong> ও <strong>সর্বনিম্ন</strong>। ধরনগুলো সেট করা হয় <strong>সেটিংস → কনজিউমেবল</strong>-এ, এবং প্রতিটি ধরনের নিজস্ব ফিল্ড থাকতে পারে <strong>সিস্টেম → কাস্টম ফিল্ড → কনজিউমেবল</strong>-এ - টোনারের জন্য পৃষ্ঠার ক্ষমতা, কাগজের জন্য ওজন।',
        'help_p2' => '<strong>স্টক চলাচল।</strong> একটি আইটেম খুলুন, তারপর একটি ডেলিভারি <strong>গ্রহণ</strong> করুন (পরিমাণ, দাম, সরবরাহকারী, ইনভয়েস নম্বর ও তারিখ - নতুন দামের ডেলিভারি চলতি দাম হয়ে যায়), কোনো ব্যক্তিকে কিছু <strong>ইস্যু</strong> করুন, অথবা একটি <strong>ফেরত</strong> নিন। স্টক কখনো শূন্যের নিচে যায় না: যা আছে তার চেয়ে বেশি ইস্যু করা প্রত্যাখ্যাত হয়। <strong>সমন্বয়</strong> (নষ্ট বা পাওয়া স্টকের জন্য, কারণসহ) করতে সিস্টেম → ভূমিকায় <em>কনজিউমেবল স্টক সমন্বয়</em> অনুমতি লাগে।',
        'help_p3' => '<strong>টিকিটের বিপরীতে।</strong> কোনো টিকিটে <strong>লিঙ্ক করুন... → কনজিউমেবল</strong> এই স্ক্রিনটি খোলে, প্রতিটি আইটেমের পাশে <strong>ইস্যু</strong> সহ, টিকিট ও তার অনুরোধকারীকে দিয়ে পূরণ করা অবস্থায়। ইস্যুটি টিকিটের ইতিহাসে এবং আইটেমের ইতিহাসে দেখা যায়।',
        'help_p9' => '<strong>কনজিউমেবল ব্যবহার।</strong> তালিকায় কোনো টিকিটে রাইট-ক্লিক করে <strong>কনজিউমেবল ব্যবহার করুন</strong> বেছে নিন: টিকিটের কোম্পানির প্রথম ১০টি আইটেম, কতটি স্টকে আছে সহ, এবং একটি সার্চ বক্স। একটি বেছে নিলে টিকিটের বিপরীতে, তার অনুরোধকারীকে, একটি ইস্যু হয়। টিকিটের <strong>লিঙ্ক</strong>-এ কী ব্যবহৃত হয়েছে দেখা যায় - ক্রস চিহ্নটি কারণসহ তা আনডু করে। একটি অনুরোধ ফর্ম জিজ্ঞেস করতে পারে <strong>কোন</strong> কনজিউমেবল: ফর্মে <strong>কনজিউমেবল</strong>-এর উপর একটি <strong>লুকআপ</strong> প্রশ্ন যোগ করুন (এটি পোর্টালেও ব্যবহার করা যায়)। এ থেকে তোলা টিকিটে চাওয়া আইটেমটি একটি ড্যাশ-রেখার পিল হিসেবে দেখায় - একটি ব্যবহার করতে এতে ক্লিক করুন। চাওয়ায় কখনো স্টক সরে না; শুধু ব্যবহার করলেই সরে।',
        'help_p4' => '<strong>সবকিছু রেকর্ড হয়।</strong> কেউ স্টকের সংখ্যা টাইপ করে না - প্রতিটি গ্রহণ, ইস্যু, ফেরত ও সমন্বয় আইটেমের <strong>চলাচল</strong>-এ একটি লাইন, কে, কখন, কাকে, টিকিট এবং তখনকার মূল্যসহ। ভুল শুধরানো হয় <strong>আনডু</strong> ও একটি কারণ দিয়ে: মূল এন্ট্রি থাকে, তার পাশে আনডু দেখা যায়। আইটেমের নিজের পরিবর্তনগুলো এর <strong>ইতিহাস</strong> ট্যাবে থাকে।',
        'help_p5' => '<strong>কমে যাওয়া।</strong> <strong>পুনরায় অর্ডারের স্তর</strong>-এ বা এর নিচে আইটেমটি <em>কম</em> চিহ্নিত হয়, Watchtower-এ <em>কম স্টক</em>-এর অধীনে গণনা হয়, এবং সেটিংস → কনজিউমেবল-এ বেছে নেওয়া ব্যক্তিরা একটি বেল বিজ্ঞপ্তি পান - প্রতিবার নামার সময় একবার। <strong>পুনরায় অর্ডার</strong> সেখানে বেছে নেওয়া রিকুইজিশন ফর্ম খোলে, আইটেম, তার সরবরাহকারী ও একটি প্রস্তাবিত পরিমাণ দিয়ে পূরণ করা অবস্থায়, এবং এটি সেই ফর্মের অনুমোদনের মধ্য দিয়ে যায়।',
        'help_p6' => '<strong>স্টক গণনা।</strong> একটি শুরু করুন, তাকগুলো ঘুরে দেখুন এবং আসলে যা আছে তা টাইপ করুন। প্রতিটি লাইনে ওই মুহূর্তে রেকর্ড অনুযায়ী যা প্রত্যাশিত ছিল, যা গণনা করা হলো, পার্থক্য ও তার মূল্য সংরক্ষিত থাকে - ১০ প্রত্যাশা করে ৮ পেলে -২ রেকর্ড হয়। <strong>শেষ করুন</strong> স্টক ঠিক করে এবং এর জন্য <em>কনজিউমেবল স্টক সমন্বয়</em> অনুমতি লাগে; <strong>বাতিল</strong> কিছুই বদলায় না।',
        'help_p7' => '<strong>পার্থক্য</strong> দেখায় স্টক গণনায় মাস অনুযায়ী, টাকায় বা এককে, কী কম বা বেশি পাওয়া গেছে, এবং কোন আইটেমগুলো সবচেয়ে বেশি হারায়। কম ও বেশি আলাদা করে দেখানো হয়, যাতে একটি অন্যটিকে ঢেকে না দেয়।',
    ],
];
